-- RTJ scope linked to the neutralization loops (Section Head, 25 Oct 2026). The 236 RTJ flanges of the inspection
-- worklist (attachment 4, 18 lines) are part of the neutralization loop scope: no separate RTJ progress, steps, alerts or
-- follow-up. Each RTJ keeps its line, ISO sheet and size, linked to its loop for traceability (matched by line number
-- through the P&ID lineup and the loop records; "unverified" where the match is not certain; no loop where none covers
-- the line). An RTJ counts as handed over when its loop's items are recorded handed over (stage), never because the
-- loop is neutralized. Handed over does not mean the RTJ maintenance or inspection is done; new work goes on an IAT.
-- The 17 "RTJ & injection" follow-up items (loop items named by location; no planned hours) leave the Equipment list
-- (covered_by = their loop); their records, stage and history stay and their handover is recorded from the loop.
create table if not exists public.trk_rtj (
  id uuid primary key default gen_random_uuid(),
  tracker_id uuid not null references public.trk_trackers(id),
  point_id uuid references public.trk_points(id),
  seq int not null, line text not null, iso_sheet text, rtj_no text not null, size text, fitting text, insp_freq int,
  link text check (link is null or link in ('lineup', 'unverified')), link_note text,
  source text not null default 'Inspection worklist Nov 2026 · attachment 4 (RTJ list)',
  created_at timestamptz not null default now(),
  unique (tracker_id, seq)
);
comment on column public.trk_rtj.seq is 'Row of the worklist RTJ list (the list repeats some RTJ numbers).';
comment on table public.trk_rtj is 'RTJ flanges of the inspection worklist, linked to their neutralization loop (point_id). Reference only: no progress of their own; handed over with the loop.';
alter table public.trk_rtj enable row level security;
create policy trk_rtj_read on public.trk_rtj for select using (((select public.app_current_role()) is not null) or (tracker_id = (select public.trk_access_tracker())));
create policy trk_rtj_head on public.trk_rtj for all using (public.app_is_section_head()) with check (public.app_is_section_head());
revoke all on public.trk_rtj from anon, authenticated;
grant select on public.trk_rtj to anon, authenticated;
grant insert, update on public.trk_rtj to authenticated;

alter table public.trk_equipment add column if not exists covered_by text;
comment on column public.trk_equipment.covered_by is 'Covered by this neutralization loop (ref): not listed under Equipment, no follow-up of its own; handover recorded from the loop. Display only.';

